return items.map(item => {
  const row = item.json;
  return {
    json: {
      source: 'google_sheets',
      week_start: row.week_start || '',
      channel: row.channel || 'General',
      metric_name: row.metric_name || 'Unknown Metric',
      current_value: Number(row.current_value || 0),
      previous_value: Number(row.previous_value || 0),
      target_value: Number(row.target_value || 0),
      notes: row.notes || ''
    }
  };
});

const limited = items.slice(0, 5);
return limited.map((item, index) => {
  return {
    json: {
      source: 'api_data',
      week_start: new Date().toISOString().slice(0, 10),
      channel: 'Benchmark',
      metric_name: `Test KPI ${index + 1}`,
      current_value: item.json.id || 0,
      previous_value: (item.json.id || 0) - 1,
      target_value: (item.json.id || 0) + 2,
      notes: item.json.title || ''
    }
  };
});

return items.map(item => {
  const d = item.json;
  const current = Number(d.current_value || 0);
  const previous = Number(d.previous_value || 0);
  const target = Number(d.target_value || 0);

  const diff = current - previous;
  const pct_change = previous !== 0 ? ((diff / previous) * 100) : 0;
  const target_gap = current - target;

  let trend = 'flat';
  if (diff > 0) trend = 'up';
  if (diff < 0) trend = 'down';

  let target_status = 'on_target';
  if (current > target) target_status = 'above_target';
  if (current < target) target_status = 'below_target';

  return {
    json: {
      ...d,
      diff,
      pct_change: Number(pct_change.toFixed(2)),
      target_gap,
      trend,
      target_status
    }
  };
});

const aiOutput = items[0].json;
const summaryText =
  aiOutput.text ||
  aiOutput.output ||
  aiOutput.response ||
  JSON.stringify(aiOutput);

const date = new Date().toISOString().slice(0, 10);

return [
  {
    json: {
      email_subject: `Weekly KPI Executive Summary - ${date}`,
      email_body: `Hello Team,

Please find this week's KPI executive summary below.

${summaryText}

Generated automatically from n8n.`,
      slack_message: `Weekly KPI Executive Summary\n\n${summaryText}`
    }
  }
];
